rg -n 'DefaultBodyLimit|body_limit|MAX_.*BODY|32 \*|1024.*1024|snapshot.*limit' crates apps/mcp/src | rg 'bridge|classic' | head -35; python3 - <<'PY'
import pathlib,json,os
roots=[pathlib.Path.home()/'.opencut',pathlib.Path('/tmp/opencut')]
for root in roots:
 for p in [root/'mcp-classic-bridge.json',*list((root/'mcp-classic-bridges').glob('*.json'))]:
  try:
   x=json.load(open(p));os.kill(x['pid'],0)
   print({k:x.get(k)for k in ['pid','version','supportsHeartbeat','baseUrl','createdAtMs']})
  except:pass
PY

